export const files: Record<string, string> = {
  ".env.example": "# Inventory Tracker needs no environment variables or API keys.\n# Everything — products, suppliers, and stock movements — is stored\n# locally in your browser (localStorage). Nothing is sent to a server.\n",
  "README.md": "# Inventory Tracker\n\nTrack stock levels, suppliers, and every movement in and out — with\nlow-stock alerts and live inventory value.\n\n## Features\n\n- A products catalog: name, SKU, category, quantity on hand, reorder\n  threshold, unit cost, and a linked supplier.\n- Adjust stock with a signed quantity and a reason (restock, sale,\n  damaged, correction) — every adjustment is logged with a timestamp.\n- A movements log listing every stock change across all products,\n  newest first, filterable by product.\n- A suppliers list (name, contact email, phone) linked from products.\n- A dashboard with total inventory value, total SKUs, and a count of\n  products at or below their reorder threshold.\n- Low-stock products are flagged throughout the app so they're easy to\n  spot before you run out.\n- Search and category filtering across the product catalog.\n- Full create/edit/delete for products, suppliers, and adjustments.\n\n## Getting started\n\n```bash\nnpm install\nnpm run dev\n```\n\n## Build\n\n```bash\nnpm run build\n```\n\n## Data storage\n\nProducts, suppliers, and stock movements are stored in your browser's\n`localStorage`. Nothing leaves your device, and there is no account or\nsign-in.\n",
  "index.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Inventory Tracker</title>\n  </head>\n  <body>\n    <div id=\"root\"></div>\n    <script type=\"module\" src=\"/src/main.tsx\"></script>\n  </body>\n</html>\n",
  "package.json": "{\n  \"name\": \"inventory-tracker\",\n  \"private\": true,\n  \"version\": \"1.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"build\": \"vite build\",\n    \"preview\": \"vite preview\"\n  },\n  \"dependencies\": {\n    \"lucide-react\": \"^0.417.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\"\n  },\n  \"devDependencies\": {\n    \"@types/react\": \"^18.3.3\",\n    \"@types/react-dom\": \"^18.3.0\",\n    \"@vitejs/plugin-react\": \"^4.3.1\",\n    \"autoprefixer\": \"^10.4.19\",\n    \"postcss\": \"^8.4.40\",\n    \"tailwindcss\": \"^3.4.7\",\n    \"typescript\": \"^5.5.4\",\n    \"vite\": \"^5.4.0\"\n  }\n}\n",
  "postcss.config.js": "export default {\n  plugins: {\n    tailwindcss: {},\n    autoprefixer: {},\n  },\n};\n",
  "src/App.tsx": "import { useEffect, useState } from \"react\";\nimport type { Movement, MovementReason, Product, Supplier } from \"./types\";\nimport {\n  hasSeeded,\n  loadMovements,\n  loadProducts,\n  loadSuppliers,\n  markSeeded,\n  saveMovements,\n  saveProducts,\n  saveSuppliers,\n} from \"./lib/storage\";\nimport { seedMovements, seedProducts, seedSuppliers } from \"./lib/seed\";\nimport { NavBar, type NavView } from \"./components/NavBar\";\nimport { Dashboard } from \"./components/Dashboard\";\nimport { ProductsPanel } from \"./components/ProductsPanel\";\nimport { MovementsPanel } from \"./components/MovementsPanel\";\nimport { SuppliersPanel } from \"./components/SuppliersPanel\";\n\nfunction initialState() {\n  if (hasSeeded()) {\n    return { suppliers: loadSuppliers(), products: loadProducts(), movements: loadMovements() };\n  }\n  const suppliers = seedSuppliers();\n  const products = seedProducts(suppliers);\n  const movements = seedMovements(products);\n  markSeeded();\n  return { suppliers, products, movements };\n}\n\nexport default function App() {\n  const [{ suppliers: initialSuppliers, products: initialProducts, movements: initialMovements }] = useState(initialState);\n  const [suppliers, setSuppliers] = useState<Supplier[]>(initialSuppliers);\n  const [products, setProducts] = useState<Product[]>(initialProducts);\n  const [movements, setMovements] = useState<Movement[]>(initialMovements);\n  const [view, setView] = useState<NavView>(\"dashboard\");\n\n  useEffect(() => saveSuppliers(suppliers), [suppliers]);\n  useEffect(() => saveProducts(products), [products]);\n  useEffect(() => saveMovements(movements), [movements]);\n\n  function addSupplier(data: Omit<Supplier, \"id\" | \"createdAt\">) {\n    setSuppliers((prev) => [...prev, { ...data, id: crypto.randomUUID(), createdAt: Date.now() }]);\n  }\n  function updateSupplier(id: string, data: Omit<Supplier, \"id\" | \"createdAt\">) {\n    setSuppliers((prev) => prev.map((s) => (s.id === id ? { ...s, ...data } : s)));\n  }\n  function deleteSupplier(id: string) {\n    setSuppliers((prev) => prev.filter((s) => s.id !== id));\n  }\n\n  function addProduct(data: Omit<Product, \"id\" | \"createdAt\">) {\n    setProducts((prev) => [...prev, { ...data, id: crypto.randomUUID(), createdAt: Date.now() }]);\n  }\n  function updateProduct(id: string, data: Omit<Product, \"id\" | \"createdAt\">) {\n    setProducts((prev) => prev.map((p) => (p.id === id ? { ...p, ...data } : p)));\n  }\n  function deleteProduct(id: string) {\n    setProducts((prev) => prev.filter((p) => p.id !== id));\n    setMovements((prev) => prev.filter((m) => m.productId !== id));\n  }\n\n  function adjustStock(productId: string, delta: number, reason: MovementReason, note: string) {\n    setProducts((prev) =>\n      prev.map((p) => (p.id === productId ? { ...p, quantity: Math.max(0, p.quantity + delta) } : p))\n    );\n    setMovements((prev) => [...prev, { id: crypto.randomUUID(), productId, delta, reason, note, createdAt: Date.now() }]);\n  }\n\n  return (\n    <div className=\"min-h-screen bg-gradient-to-b from-teal-50/40 via-slate-50 to-slate-50\">\n      <NavBar view={view} onNavigate={setView} />\n      <main className=\"mx-auto max-w-5xl px-4 py-8\">\n        {view === \"dashboard\" && <Dashboard products={products} onViewProducts={() => setView(\"products\")} />}\n        {view === \"products\" && (\n          <ProductsPanel\n            products={products}\n            suppliers={suppliers}\n            onAdd={addProduct}\n            onUpdate={updateProduct}\n            onDelete={deleteProduct}\n            onAdjust={adjustStock}\n          />\n        )}\n        {view === \"movements\" && <MovementsPanel movements={movements} products={products} />}\n        {view === \"suppliers\" && (\n          <SuppliersPanel suppliers={suppliers} onAdd={addSupplier} onUpdate={updateSupplier} onDelete={deleteSupplier} />\n        )}\n      </main>\n    </div>\n  );\n}\n",
  "src/components/Dashboard.tsx": "import { useMemo } from \"react\";\nimport { AlertTriangle, Layers, Wallet } from \"lucide-react\";\nimport type { Product } from \"../types\";\nimport { formatCurrency, inventoryValue, isLowStock } from \"../lib/calc\";\n\ninterface Props {\n  products: Product[];\n  onViewProducts: () => void;\n}\n\nexport function Dashboard({ products, onViewProducts }: Props) {\n  const lowStock = useMemo(() => products.filter(isLowStock), [products]);\n  const value = useMemo(() => inventoryValue(products), [products]);\n\n  return (\n    <div>\n      <div className=\"grid gap-3 sm:grid-cols-3\">\n        <div className=\"rounded-2xl border border-teal-100/70 bg-white p-4 shadow-sm\">\n          <div className=\"flex items-center gap-2 text-xs font-medium uppercase tracking-wide text-slate-400\">\n            <Wallet className=\"h-3.5 w-3.5\" /> Inventory value\n          </div>\n          <p className=\"mt-1.5 text-2xl font-semibold text-slate-900\">{formatCurrency(value)}</p>\n        </div>\n        <div className=\"rounded-2xl border border-teal-100/70 bg-white p-4 shadow-sm\">\n          <div className=\"flex items-center gap-2 text-xs font-medium uppercase tracking-wide text-slate-400\">\n            <Layers className=\"h-3.5 w-3.5\" /> Total SKUs\n          </div>\n          <p className=\"mt-1.5 text-2xl font-semibold text-slate-900\">{products.length}</p>\n        </div>\n        <button\n          type=\"button\"\n          onClick={onViewProducts}\n          className=\"rounded-2xl border border-amber-200 bg-amber-50 p-4 text-left shadow-sm transition-colors hover:border-amber-300\"\n        >\n          <div className=\"flex items-center gap-2 text-xs font-medium uppercase tracking-wide text-amber-600\">\n            <AlertTriangle className=\"h-3.5 w-3.5\" /> Low stock\n          </div>\n          <p className=\"mt-1.5 text-2xl font-semibold text-amber-700\">{lowStock.length}</p>\n        </button>\n      </div>\n\n      {lowStock.length > 0 && (\n        <div className=\"mt-5\">\n          <h2 className=\"mb-2 text-sm font-semibold text-slate-900\">Needs reordering</h2>\n          <div className=\"space-y-1.5\">\n            {lowStock.map((p) => (\n              <div\n                key={p.id}\n                className=\"flex items-center justify-between rounded-xl border border-amber-100 bg-amber-50/60 px-3.5 py-2.5 text-sm\"\n              >\n                <div>\n                  <p className=\"font-medium text-slate-800\">{p.name}</p>\n                  <p className=\"text-xs text-slate-500\">{p.sku}</p>\n                </div>\n                <p className=\"text-xs font-semibold text-amber-700\">\n                  {p.quantity} on hand · reorder at {p.reorderThreshold}\n                </p>\n              </div>\n            ))}\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/components/MovementsPanel.tsx": "import { useMemo, useState } from \"react\";\nimport { ArrowDownCircle, ArrowUpCircle } from \"lucide-react\";\nimport type { Movement, Product } from \"../types\";\nimport { formatDate } from \"../lib/calc\";\n\ninterface Props {\n  movements: Movement[];\n  products: Product[];\n}\n\nexport function MovementsPanel({ movements, products }: Props) {\n  const [productFilter, setProductFilter] = useState(\"All\");\n\n  const productName = (id: string) => products.find((p) => p.id === id)?.name ?? \"Deleted product\";\n\n  const visible = useMemo(() => {\n    const list = productFilter === \"All\" ? movements : movements.filter((m) => m.productId === productFilter);\n    return [...list].sort((a, b) => b.createdAt - a.createdAt);\n  }, [movements, productFilter]);\n\n  return (\n    <div className=\"mx-auto max-w-3xl\">\n      <div className=\"mb-4 flex flex-wrap items-center justify-between gap-2\">\n        <h2 className=\"text-lg font-semibold text-slate-900\">Movements</h2>\n        <select\n          value={productFilter}\n          onChange={(e) => setProductFilter(e.target.value)}\n          className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n        >\n          <option value=\"All\">All products</option>\n          {products.map((p) => (\n            <option key={p.id} value={p.id}>\n              {p.name}\n            </option>\n          ))}\n        </select>\n      </div>\n\n      {visible.length === 0 ? (\n        <p className=\"rounded-xl border border-dashed border-slate-300 p-8 text-center text-sm text-slate-500\">\n          No stock movements yet. Adjust a product's stock to see it logged here.\n        </p>\n      ) : (\n        <div className=\"space-y-1.5\">\n          {visible.map((m) => (\n            <div key={m.id} className=\"flex items-center justify-between gap-3 rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 text-sm\">\n              <div className=\"flex items-center gap-2.5\">\n                {m.delta >= 0 ? (\n                  <ArrowUpCircle className=\"h-4 w-4 shrink-0 text-emerald-500\" />\n                ) : (\n                  <ArrowDownCircle className=\"h-4 w-4 shrink-0 text-red-500\" />\n                )}\n                <div>\n                  <p className=\"font-medium text-slate-800\">{productName(m.productId)}</p>\n                  <p className=\"text-xs capitalize text-slate-500\">\n                    {m.reason}\n                    {m.note ? ` — ${m.note}` : \"\"}\n                  </p>\n                </div>\n              </div>\n              <div className=\"shrink-0 text-right\">\n                <p className={m.delta >= 0 ? \"font-semibold text-emerald-600\" : \"font-semibold text-red-600\"}>\n                  {m.delta >= 0 ? \"+\" : \"\"}\n                  {m.delta}\n                </p>\n                <p className=\"text-xs text-slate-400\">{formatDate(m.createdAt)}</p>\n              </div>\n            </div>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/components/NavBar.tsx": "import { Boxes, LayoutDashboard, ListTree, Package, Truck } from \"lucide-react\";\n\nexport type NavView = \"dashboard\" | \"products\" | \"movements\" | \"suppliers\";\n\ninterface Props {\n  view: NavView;\n  onNavigate: (view: NavView) => void;\n}\n\nfunction navClass(active: boolean) {\n  return `flex items-center gap-1.5 rounded-full px-3 py-1.5 text-sm font-medium transition-colors ${\n    active ? \"bg-slate-900 text-white shadow-sm\" : \"text-slate-500 hover:bg-slate-100 hover:text-slate-800\"\n  }`;\n}\n\nexport function NavBar({ view, onNavigate }: Props) {\n  return (\n    <header className=\"border-b border-teal-100/60 bg-white/90 backdrop-blur-sm\">\n      <div className=\"mx-auto flex max-w-5xl flex-wrap items-center gap-3 px-4 py-3.5\">\n        <h1 className=\"flex items-center gap-2 text-base font-bold tracking-tight text-slate-900\">\n          <span className=\"flex h-8 w-8 items-center justify-center rounded-xl bg-gradient-to-br from-slate-800 to-slate-950 text-teal-400 shadow-sm\">\n            <Boxes className=\"h-4 w-4\" />\n          </span>\n          Inventory\n        </h1>\n        <nav className=\"flex items-center gap-1\">\n          <button type=\"button\" onClick={() => onNavigate(\"dashboard\")} className={navClass(view === \"dashboard\")}>\n            <LayoutDashboard className=\"h-3.5 w-3.5\" /> Dashboard\n          </button>\n          <button type=\"button\" onClick={() => onNavigate(\"products\")} className={navClass(view === \"products\")}>\n            <Package className=\"h-3.5 w-3.5\" /> Products\n          </button>\n          <button type=\"button\" onClick={() => onNavigate(\"movements\")} className={navClass(view === \"movements\")}>\n            <ListTree className=\"h-3.5 w-3.5\" /> Movements\n          </button>\n          <button type=\"button\" onClick={() => onNavigate(\"suppliers\")} className={navClass(view === \"suppliers\")}>\n            <Truck className=\"h-3.5 w-3.5\" /> Suppliers\n          </button>\n        </nav>\n      </div>\n    </header>\n  );\n}\n",
  "src/components/ProductsPanel.tsx": "import { useMemo, useState } from \"react\";\nimport { PackagePlus, Pencil, Plus, Search, Trash2, X } from \"lucide-react\";\nimport type { MovementReason, Product, Supplier } from \"../types\";\nimport { MOVEMENT_REASONS } from \"../types\";\nimport { formatCurrency, isLowStock } from \"../lib/calc\";\n\ninterface FormState {\n  name: string;\n  sku: string;\n  category: string;\n  quantity: string;\n  reorderThreshold: string;\n  unitCost: string;\n  supplierId: string;\n}\n\nfunction emptyForm(supplierId: string): FormState {\n  return { name: \"\", sku: \"\", category: \"\", quantity: \"0\", reorderThreshold: \"0\", unitCost: \"0\", supplierId };\n}\n\nfunction toProductData(form: FormState): Omit<Product, \"id\" | \"createdAt\"> {\n  return {\n    name: form.name.trim(),\n    sku: form.sku.trim(),\n    category: form.category.trim() || \"Uncategorized\",\n    quantity: Math.max(0, Math.floor(Number(form.quantity) || 0)),\n    reorderThreshold: Math.max(0, Math.floor(Number(form.reorderThreshold) || 0)),\n    unitCost: Math.max(0, Number(form.unitCost) || 0),\n    supplierId: form.supplierId,\n  };\n}\n\ninterface Props {\n  products: Product[];\n  suppliers: Supplier[];\n  onAdd: (data: Omit<Product, \"id\" | \"createdAt\">) => void;\n  onUpdate: (id: string, data: Omit<Product, \"id\" | \"createdAt\">) => void;\n  onDelete: (id: string) => void;\n  onAdjust: (productId: string, delta: number, reason: MovementReason, note: string) => void;\n}\n\nexport function ProductsPanel({ products, suppliers, onAdd, onUpdate, onDelete, onAdjust }: Props) {\n  const [search, setSearch] = useState(\"\");\n  const [categoryFilter, setCategoryFilter] = useState(\"All\");\n  const [adding, setAdding] = useState(false);\n  const [form, setForm] = useState<FormState>(emptyForm(suppliers[0]?.id ?? \"\"));\n  const [editingId, setEditingId] = useState<string | null>(null);\n  const [editForm, setEditForm] = useState<FormState>(emptyForm(\"\"));\n  const [confirmingId, setConfirmingId] = useState<string | null>(null);\n  const [adjustingId, setAdjustingId] = useState<string | null>(null);\n  const [adjustDelta, setAdjustDelta] = useState(\"0\");\n  const [adjustReason, setAdjustReason] = useState<MovementReason>(\"restock\");\n  const [adjustNote, setAdjustNote] = useState(\"\");\n  const [error, setError] = useState(\"\");\n\n  const supplierName = (id: string) => suppliers.find((s) => s.id === id)?.name ?? \"No supplier\";\n\n  const categories = useMemo(() => {\n    const set = new Set(products.map((p) => p.category));\n    return [\"All\", ...Array.from(set).sort()];\n  }, [products]);\n\n  const visible = useMemo(() => {\n    return products.filter((p) => {\n      if (categoryFilter !== \"All\" && p.category !== categoryFilter) return false;\n      if (!search.trim()) return true;\n      const q = search.trim().toLowerCase();\n      return p.name.toLowerCase().includes(q) || p.sku.toLowerCase().includes(q);\n    });\n  }, [products, search, categoryFilter]);\n\n  function submitAdd(e: React.FormEvent) {\n    e.preventDefault();\n    if (!form.name.trim() || !form.sku.trim()) {\n      setError(\"Name and SKU are required.\");\n      return;\n    }\n    onAdd(toProductData(form));\n    setForm(emptyForm(suppliers[0]?.id ?? \"\"));\n    setAdding(false);\n    setError(\"\");\n  }\n\n  function startEdit(p: Product) {\n    setEditingId(p.id);\n    setEditForm({\n      name: p.name,\n      sku: p.sku,\n      category: p.category,\n      quantity: String(p.quantity),\n      reorderThreshold: String(p.reorderThreshold),\n      unitCost: String(p.unitCost),\n      supplierId: p.supplierId,\n    });\n  }\n\n  function submitEdit(e: React.FormEvent) {\n    e.preventDefault();\n    if (!editingId) return;\n    if (!editForm.name.trim() || !editForm.sku.trim()) {\n      setError(\"Name and SKU are required.\");\n      return;\n    }\n    onUpdate(editingId, toProductData(editForm));\n    setEditingId(null);\n    setError(\"\");\n  }\n\n  function startAdjust(p: Product) {\n    setAdjustingId(p.id);\n    setAdjustDelta(\"0\");\n    setAdjustReason(\"restock\");\n    setAdjustNote(\"\");\n  }\n\n  function submitAdjust(e: React.FormEvent) {\n    e.preventDefault();\n    const delta = Math.trunc(Number(adjustDelta) || 0);\n    if (!adjustingId || delta === 0) {\n      setAdjustingId(null);\n      return;\n    }\n    onAdjust(adjustingId, delta, adjustReason, adjustNote.trim());\n    setAdjustingId(null);\n  }\n\n  const adjustingProduct = products.find((p) => p.id === adjustingId);\n\n  return (\n    <div className=\"mx-auto max-w-4xl\">\n      <div className=\"mb-4 flex flex-wrap items-center justify-between gap-2\">\n        <h2 className=\"text-lg font-semibold text-slate-900\">Products</h2>\n        {!adding && (\n          <button\n            type=\"button\"\n            onClick={() => setAdding(true)}\n            className=\"flex items-center gap-1.5 rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\"\n          >\n            <Plus className=\"h-4 w-4\" /> Add product\n          </button>\n        )}\n      </div>\n\n      <div className=\"mb-4 flex flex-wrap items-center gap-2\">\n        <div className=\"relative flex-1 min-w-[180px]\">\n          <Search className=\"pointer-events-none absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-slate-400\" />\n          <input\n            value={search}\n            onChange={(e) => setSearch(e.target.value)}\n            placeholder=\"Search name or SKU\"\n            className=\"w-full rounded-lg border border-slate-200 py-2 pl-8 pr-3 text-sm outline-none focus:border-slate-400\"\n          />\n        </div>\n        <select\n          value={categoryFilter}\n          onChange={(e) => setCategoryFilter(e.target.value)}\n          className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n        >\n          {categories.map((c) => (\n            <option key={c} value={c}>\n              {c}\n            </option>\n          ))}\n        </select>\n      </div>\n\n      {error && <p className=\"mb-3 text-sm text-red-600\">{error}</p>}\n\n      {adding && (\n        <form onSubmit={submitAdd} className=\"mb-4 space-y-2 rounded-xl border border-slate-200 p-4\">\n          <div className=\"grid gap-2 sm:grid-cols-2\">\n            <input\n              autoFocus\n              value={form.name}\n              onChange={(e) => setForm({ ...form, name: e.target.value })}\n              placeholder=\"Product name\"\n              className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n            />\n            <input\n              value={form.sku}\n              onChange={(e) => setForm({ ...form, sku: e.target.value })}\n              placeholder=\"SKU\"\n              className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n            />\n            <input\n              value={form.category}\n              onChange={(e) => setForm({ ...form, category: e.target.value })}\n              placeholder=\"Category\"\n              className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n            />\n            <select\n              value={form.supplierId}\n              onChange={(e) => setForm({ ...form, supplierId: e.target.value })}\n              className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n            >\n              <option value=\"\">No supplier</option>\n              {suppliers.map((s) => (\n                <option key={s.id} value={s.id}>\n                  {s.name}\n                </option>\n              ))}\n            </select>\n            <input\n              type=\"number\"\n              min={0}\n              value={form.quantity}\n              onChange={(e) => setForm({ ...form, quantity: e.target.value })}\n              placeholder=\"Quantity on hand\"\n              className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n            />\n            <input\n              type=\"number\"\n              min={0}\n              value={form.reorderThreshold}\n              onChange={(e) => setForm({ ...form, reorderThreshold: e.target.value })}\n              placeholder=\"Reorder threshold\"\n              className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n            />\n            <input\n              type=\"number\"\n              min={0}\n              step={0.01}\n              value={form.unitCost}\n              onChange={(e) => setForm({ ...form, unitCost: e.target.value })}\n              placeholder=\"Unit cost\"\n              className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n            />\n          </div>\n          <div className=\"flex justify-end gap-2\">\n            <button\n              type=\"button\"\n              onClick={() => {\n                setAdding(false);\n                setError(\"\");\n              }}\n              className=\"rounded-lg px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-100\"\n            >\n              Cancel\n            </button>\n            <button type=\"submit\" className=\"rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\">\n              Save\n            </button>\n          </div>\n        </form>\n      )}\n\n      {visible.length === 0 ? (\n        <p className=\"rounded-xl border border-dashed border-slate-300 p-8 text-center text-sm text-slate-500\">\n          No products match. Try a different search or add one.\n        </p>\n      ) : (\n        <div className=\"overflow-x-auto rounded-2xl border border-teal-100/70 bg-white shadow-sm\">\n          <table className=\"w-full min-w-[720px] text-sm\">\n            <thead className=\"border-b border-slate-200 bg-slate-50 text-left text-xs uppercase text-slate-400\">\n              <tr>\n                <th className=\"px-4 py-2.5 font-medium\">Product</th>\n                <th className=\"px-4 py-2.5 font-medium\">Category</th>\n                <th className=\"px-4 py-2.5 font-medium\">Qty</th>\n                <th className=\"px-4 py-2.5 font-medium\">Unit cost</th>\n                <th className=\"px-4 py-2.5 font-medium\">Supplier</th>\n                <th className=\"px-4 py-2.5 font-medium\" />\n              </tr>\n            </thead>\n            <tbody className=\"divide-y divide-slate-100\">\n              {visible.map((p) =>\n                editingId === p.id ? (\n                  <tr key={p.id}>\n                    <td colSpan={6} className=\"px-4 py-3\">\n                      <form onSubmit={submitEdit} className=\"grid gap-2 sm:grid-cols-3\">\n                        <input\n                          autoFocus\n                          value={editForm.name}\n                          onChange={(e) => setEditForm({ ...editForm, name: e.target.value })}\n                          className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                        />\n                        <input\n                          value={editForm.sku}\n                          onChange={(e) => setEditForm({ ...editForm, sku: e.target.value })}\n                          className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                        />\n                        <input\n                          value={editForm.category}\n                          onChange={(e) => setEditForm({ ...editForm, category: e.target.value })}\n                          className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                        />\n                        <input\n                          type=\"number\"\n                          min={0}\n                          value={editForm.reorderThreshold}\n                          onChange={(e) => setEditForm({ ...editForm, reorderThreshold: e.target.value })}\n                          placeholder=\"Reorder threshold\"\n                          className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                        />\n                        <input\n                          type=\"number\"\n                          min={0}\n                          step={0.01}\n                          value={editForm.unitCost}\n                          onChange={(e) => setEditForm({ ...editForm, unitCost: e.target.value })}\n                          placeholder=\"Unit cost\"\n                          className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                        />\n                        <select\n                          value={editForm.supplierId}\n                          onChange={(e) => setEditForm({ ...editForm, supplierId: e.target.value })}\n                          className=\"rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                        >\n                          <option value=\"\">No supplier</option>\n                          {suppliers.map((s) => (\n                            <option key={s.id} value={s.id}>\n                              {s.name}\n                            </option>\n                          ))}\n                        </select>\n                        <div className=\"col-span-full flex justify-end gap-2\">\n                          <button type=\"button\" onClick={() => setEditingId(null)} className=\"rounded-lg px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-100\">\n                            Cancel\n                          </button>\n                          <button type=\"submit\" className=\"rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\">\n                            Save\n                          </button>\n                        </div>\n                      </form>\n                    </td>\n                  </tr>\n                ) : (\n                  <tr key={p.id} className=\"hover:bg-slate-50/60\">\n                    <td className=\"px-4 py-2.5\">\n                      <p className=\"font-medium text-slate-800\">{p.name}</p>\n                      <p className=\"text-xs text-slate-500\">{p.sku}</p>\n                    </td>\n                    <td className=\"px-4 py-2.5 text-slate-600\">{p.category}</td>\n                    <td className=\"px-4 py-2.5\">\n                      <span className={isLowStock(p) ? \"font-semibold text-amber-700\" : \"text-slate-700\"}>{p.quantity}</span>\n                    </td>\n                    <td className=\"px-4 py-2.5 text-slate-600\">{formatCurrency(p.unitCost)}</td>\n                    <td className=\"px-4 py-2.5 text-slate-600\">{supplierName(p.supplierId)}</td>\n                    <td className=\"px-4 py-2.5\">\n                      {confirmingId === p.id ? (\n                        <div className=\"flex items-center justify-end gap-1.5\">\n                          <button\n                            type=\"button\"\n                            onClick={() => {\n                              onDelete(p.id);\n                              setConfirmingId(null);\n                            }}\n                            className=\"text-xs font-medium text-red-600\"\n                          >\n                            Delete\n                          </button>\n                          <button type=\"button\" onClick={() => setConfirmingId(null)} className=\"text-xs text-slate-400\">\n                            Cancel\n                          </button>\n                        </div>\n                      ) : (\n                        <div className=\"flex items-center justify-end gap-1 text-slate-400\">\n                          <button type=\"button\" title=\"Adjust stock\" onClick={() => startAdjust(p)} className=\"rounded p-1 hover:bg-slate-100 hover:text-slate-700\">\n                            <PackagePlus className=\"h-3.5 w-3.5\" />\n                          </button>\n                          <button type=\"button\" title=\"Edit\" onClick={() => startEdit(p)} className=\"rounded p-1 hover:bg-slate-100 hover:text-slate-700\">\n                            <Pencil className=\"h-3.5 w-3.5\" />\n                          </button>\n                          <button\n                            type=\"button\"\n                            title=\"Delete\"\n                            onClick={() => setConfirmingId(p.id)}\n                            className=\"rounded p-1 hover:bg-red-50 hover:text-red-600\"\n                          >\n                            <Trash2 className=\"h-3.5 w-3.5\" />\n                          </button>\n                        </div>\n                      )}\n                    </td>\n                  </tr>\n                )\n              )}\n            </tbody>\n          </table>\n        </div>\n      )}\n\n      {adjustingProduct && (\n        <div className=\"fixed inset-0 z-20 flex items-center justify-center bg-slate-900/40 p-4\">\n          <div className=\"w-full max-w-sm rounded-2xl bg-white p-5 shadow-xl\">\n            <div className=\"mb-3 flex items-center justify-between\">\n              <h3 className=\"text-sm font-semibold text-slate-900\">Adjust stock — {adjustingProduct.name}</h3>\n              <button type=\"button\" onClick={() => setAdjustingId(null)} className=\"rounded p-1 text-slate-400 hover:bg-slate-100\">\n                <X className=\"h-4 w-4\" />\n              </button>\n            </div>\n            <form onSubmit={submitAdjust} className=\"space-y-3\">\n              <div>\n                <label className=\"mb-1 block text-xs font-medium text-slate-600\">Quantity change (use a negative number to remove stock)</label>\n                <input\n                  autoFocus\n                  type=\"number\"\n                  value={adjustDelta}\n                  onChange={(e) => setAdjustDelta(e.target.value)}\n                  className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                />\n              </div>\n              <div>\n                <label className=\"mb-1 block text-xs font-medium text-slate-600\">Reason</label>\n                <select\n                  value={adjustReason}\n                  onChange={(e) => setAdjustReason(e.target.value as MovementReason)}\n                  className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm capitalize outline-none focus:border-slate-400\"\n                >\n                  {MOVEMENT_REASONS.map((r) => (\n                    <option key={r} value={r}>\n                      {r}\n                    </option>\n                  ))}\n                </select>\n              </div>\n              <div>\n                <label className=\"mb-1 block text-xs font-medium text-slate-600\">Note (optional)</label>\n                <input\n                  value={adjustNote}\n                  onChange={(e) => setAdjustNote(e.target.value)}\n                  className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                />\n              </div>\n              <div className=\"flex justify-end gap-2 pt-1\">\n                <button type=\"button\" onClick={() => setAdjustingId(null)} className=\"rounded-lg px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-100\">\n                  Cancel\n                </button>\n                <button type=\"submit\" className=\"rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\">\n                  Apply\n                </button>\n              </div>\n            </form>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/components/SuppliersPanel.tsx": "import { useState } from \"react\";\nimport { Pencil, Plus, Trash2 } from \"lucide-react\";\nimport type { Supplier } from \"../types\";\n\ninterface Props {\n  suppliers: Supplier[];\n  onAdd: (data: Omit<Supplier, \"id\" | \"createdAt\">) => void;\n  onUpdate: (id: string, data: Omit<Supplier, \"id\" | \"createdAt\">) => void;\n  onDelete: (id: string) => void;\n}\n\ninterface FormState {\n  name: string;\n  email: string;\n  phone: string;\n}\nconst EMPTY_FORM: FormState = { name: \"\", email: \"\", phone: \"\" };\n\nexport function SuppliersPanel({ suppliers, onAdd, onUpdate, onDelete }: Props) {\n  const [adding, setAdding] = useState(false);\n  const [form, setForm] = useState<FormState>(EMPTY_FORM);\n  const [editingId, setEditingId] = useState<string | null>(null);\n  const [editForm, setEditForm] = useState<FormState>(EMPTY_FORM);\n  const [confirmingId, setConfirmingId] = useState<string | null>(null);\n  const [error, setError] = useState(\"\");\n\n  function submitAdd(e: React.FormEvent) {\n    e.preventDefault();\n    if (!form.name.trim()) {\n      setError(\"Supplier name is required.\");\n      return;\n    }\n    onAdd({ name: form.name.trim(), email: form.email.trim(), phone: form.phone.trim() });\n    setForm(EMPTY_FORM);\n    setAdding(false);\n    setError(\"\");\n  }\n\n  function startEdit(s: Supplier) {\n    setEditingId(s.id);\n    setEditForm({ name: s.name, email: s.email, phone: s.phone });\n  }\n\n  function submitEdit(e: React.FormEvent) {\n    e.preventDefault();\n    if (!editingId) return;\n    if (!editForm.name.trim()) {\n      setError(\"Supplier name is required.\");\n      return;\n    }\n    onUpdate(editingId, { name: editForm.name.trim(), email: editForm.email.trim(), phone: editForm.phone.trim() });\n    setEditingId(null);\n    setError(\"\");\n  }\n\n  return (\n    <div className=\"mx-auto max-w-2xl\">\n      <div className=\"mb-4 flex items-center justify-between\">\n        <h2 className=\"text-lg font-semibold text-slate-900\">Suppliers</h2>\n        {!adding && (\n          <button\n            type=\"button\"\n            onClick={() => setAdding(true)}\n            className=\"flex items-center gap-1.5 rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\"\n          >\n            <Plus className=\"h-4 w-4\" /> Add supplier\n          </button>\n        )}\n      </div>\n\n      {error && <p className=\"mb-3 text-sm text-red-600\">{error}</p>}\n\n      {adding && (\n        <form onSubmit={submitAdd} className=\"mb-4 space-y-2 rounded-xl border border-slate-200 p-4\">\n          <input\n            autoFocus\n            value={form.name}\n            onChange={(e) => setForm({ ...form, name: e.target.value })}\n            placeholder=\"Supplier name\"\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n          />\n          <input\n            value={form.email}\n            onChange={(e) => setForm({ ...form, email: e.target.value })}\n            placeholder=\"Contact email\"\n            type=\"email\"\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n          />\n          <input\n            value={form.phone}\n            onChange={(e) => setForm({ ...form, phone: e.target.value })}\n            placeholder=\"Phone\"\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n          />\n          <div className=\"flex justify-end gap-2\">\n            <button\n              type=\"button\"\n              onClick={() => {\n                setAdding(false);\n                setForm(EMPTY_FORM);\n                setError(\"\");\n              }}\n              className=\"rounded-lg px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-100\"\n            >\n              Cancel\n            </button>\n            <button type=\"submit\" className=\"rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\">\n              Save\n            </button>\n          </div>\n        </form>\n      )}\n\n      {suppliers.length === 0 && !adding ? (\n        <p className=\"rounded-xl border border-dashed border-slate-300 p-8 text-center text-sm text-slate-500\">\n          No suppliers yet. Add one to link it to products.\n        </p>\n      ) : (\n        <div className=\"space-y-2\">\n          {suppliers.map((s) => (\n            <div key={s.id} className=\"rounded-xl border border-slate-200 p-3\">\n              {editingId === s.id ? (\n                <form onSubmit={submitEdit} className=\"space-y-2\">\n                  <input\n                    autoFocus\n                    value={editForm.name}\n                    onChange={(e) => setEditForm({ ...editForm, name: e.target.value })}\n                    className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                  />\n                  <input\n                    value={editForm.email}\n                    onChange={(e) => setEditForm({ ...editForm, email: e.target.value })}\n                    type=\"email\"\n                    className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                  />\n                  <input\n                    value={editForm.phone}\n                    onChange={(e) => setEditForm({ ...editForm, phone: e.target.value })}\n                    className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                  />\n                  <div className=\"flex justify-end gap-2\">\n                    <button type=\"button\" onClick={() => setEditingId(null)} className=\"rounded-lg px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-100\">\n                      Cancel\n                    </button>\n                    <button type=\"submit\" className=\"rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\">\n                      Save\n                    </button>\n                  </div>\n                </form>\n              ) : (\n                <div className=\"flex items-start justify-between gap-2\">\n                  <div>\n                    <p className=\"text-sm font-medium text-slate-900\">{s.name}</p>\n                    {s.email && <p className=\"text-xs text-slate-500\">{s.email}</p>}\n                    {s.phone && <p className=\"text-xs text-slate-500\">{s.phone}</p>}\n                  </div>\n                  {confirmingId === s.id ? (\n                    <div className=\"flex shrink-0 items-center gap-1.5\">\n                      <button\n                        type=\"button\"\n                        onClick={() => {\n                          onDelete(s.id);\n                          setConfirmingId(null);\n                        }}\n                        className=\"text-xs font-medium text-red-600\"\n                      >\n                        Delete\n                      </button>\n                      <button type=\"button\" onClick={() => setConfirmingId(null)} className=\"text-xs text-slate-400\">\n                        Cancel\n                      </button>\n                    </div>\n                  ) : (\n                    <div className=\"flex shrink-0 items-center gap-0.5 text-slate-400\">\n                      <button type=\"button\" onClick={() => startEdit(s)} title=\"Edit\" className=\"rounded p-1.5 hover:bg-slate-100 hover:text-slate-700\">\n                        <Pencil className=\"h-3.5 w-3.5\" />\n                      </button>\n                      <button\n                        type=\"button\"\n                        onClick={() => setConfirmingId(s.id)}\n                        title=\"Delete\"\n                        className=\"rounded p-1.5 hover:bg-red-50 hover:text-red-600\"\n                      >\n                        <Trash2 className=\"h-3.5 w-3.5\" />\n                      </button>\n                    </div>\n                  )}\n                </div>\n              )}\n            </div>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/index.css": "@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\nhtml {\n  -webkit-font-smoothing: antialiased;\n}\n\nbody {\n  font-family: \"Inter\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n}\n\n::-webkit-scrollbar {\n  height: 8px;\n  width: 8px;\n}\n\n::-webkit-scrollbar-thumb {\n  background-color: rgba(0, 0, 0, 0.15);\n  border-radius: 9999px;\n}\n",
  "src/lib/calc.ts": "import type { Product } from \"../types\";\n\nexport function isLowStock(product: Product): boolean {\n  return product.quantity <= product.reorderThreshold;\n}\n\nexport function inventoryValue(products: Product[]): number {\n  return products.reduce((sum, p) => sum + p.quantity * p.unitCost, 0);\n}\n\nexport function formatCurrency(amount: number): string {\n  return amount.toLocaleString(undefined, {\n    style: \"currency\",\n    currency: \"USD\",\n    minimumFractionDigits: 2,\n    maximumFractionDigits: 2,\n  });\n}\n\nexport function formatDate(ts: number): string {\n  return new Date(ts).toLocaleDateString(undefined, { month: \"short\", day: \"numeric\", year: \"numeric\" });\n}\n",
  "src/lib/seed.ts": "import type { Movement, Product, Supplier } from \"../types\";\n\nconst DAY = 24 * 60 * 60 * 1000;\n\nexport function seedSuppliers(): Supplier[] {\n  const now = Date.now();\n  return [\n    { id: crypto.randomUUID(), name: \"Northwind Traders\", email: \"orders@northwindtraders.com\", phone: \"(206) 555-0182\", createdAt: now - 90 * DAY },\n    { id: crypto.randomUUID(), name: \"Cascade Paper Co.\", email: \"sales@cascadepaper.com\", phone: \"(503) 555-0144\", createdAt: now - 75 * DAY },\n    { id: crypto.randomUUID(), name: \"Anchor Hardware Supply\", email: \"hello@anchorhardware.com\", phone: \"(415) 555-0199\", createdAt: now - 60 * DAY },\n  ];\n}\n\nexport function seedProducts(suppliers: Supplier[]): Product[] {\n  const now = Date.now();\n  const [a, b, c] = suppliers;\n  return [\n    { id: crypto.randomUUID(), name: \"Kraft Shipping Boxes (Medium)\", sku: \"BOX-MED-100\", category: \"Packaging\", quantity: 340, reorderThreshold: 100, unitCost: 0.85, supplierId: a?.id ?? \"\", createdAt: now - 88 * DAY },\n    { id: crypto.randomUUID(), name: \"Clear Packing Tape 2\\\"\", sku: \"TAPE-CLR-2\", category: \"Packaging\", quantity: 42, reorderThreshold: 50, unitCost: 2.1, supplierId: b?.id ?? \"\", createdAt: now - 84 * DAY },\n    { id: crypto.randomUUID(), name: \"Bubble Wrap Roll 12in x 100ft\", sku: \"BUB-12-100\", category: \"Packaging\", quantity: 18, reorderThreshold: 20, unitCost: 24.5, supplierId: a?.id ?? \"\", createdAt: now - 80 * DAY },\n    { id: crypto.randomUUID(), name: \"Stainless Steel Hex Bolts M8\", sku: \"BOLT-M8-SS\", category: \"Hardware\", quantity: 1250, reorderThreshold: 300, unitCost: 0.12, supplierId: c?.id ?? \"\", createdAt: now - 70 * DAY },\n    { id: crypto.randomUUID(), name: \"Cordless Drill Driver 18V\", sku: \"DRILL-18V-01\", category: \"Tools\", quantity: 9, reorderThreshold: 10, unitCost: 58.0, supplierId: c?.id ?? \"\", createdAt: now - 65 * DAY },\n    { id: crypto.randomUUID(), name: \"Safety Goggles (Clear)\", sku: \"SAFE-GOG-CL\", category: \"Safety\", quantity: 76, reorderThreshold: 25, unitCost: 3.4, supplierId: c?.id ?? \"\", createdAt: now - 55 * DAY },\n    { id: crypto.randomUUID(), name: \"A4 Copy Paper Ream\", sku: \"PPR-A4-500\", category: \"Office Supplies\", quantity: 5, reorderThreshold: 15, unitCost: 4.75, supplierId: b?.id ?? \"\", createdAt: now - 40 * DAY },\n    { id: crypto.randomUUID(), name: \"Thermal Receipt Paper Rolls\", sku: \"PPR-THM-80\", category: \"Office Supplies\", quantity: 60, reorderThreshold: 30, unitCost: 1.6, supplierId: b?.id ?? \"\", createdAt: now - 30 * DAY },\n  ];\n}\n\nexport function seedMovements(products: Product[]): Movement[] {\n  const now = Date.now();\n  const find = (sku: string) => products.find((p) => p.sku === sku);\n  const boxes = find(\"BOX-MED-100\");\n  const tape = find(\"TAPE-CLR-2\");\n  const paper = find(\"PPR-A4-500\");\n  const drill = find(\"DRILL-18V-01\");\n  const movements: Movement[] = [];\n  if (boxes) {\n    movements.push({ id: crypto.randomUUID(), productId: boxes.id, delta: 500, reason: \"restock\", note: \"Initial pallet from Northwind\", createdAt: now - 88 * DAY });\n    movements.push({ id: crypto.randomUUID(), productId: boxes.id, delta: -160, reason: \"sale\", note: \"Fulfilled outbound orders\", createdAt: now - 20 * DAY });\n  }\n  if (tape) {\n    movements.push({ id: crypto.randomUUID(), productId: tape.id, delta: 80, reason: \"restock\", note: \"\", createdAt: now - 84 * DAY });\n    movements.push({ id: crypto.randomUUID(), productId: tape.id, delta: -38, reason: \"sale\", note: \"\", createdAt: now - 12 * DAY });\n  }\n  if (paper) {\n    movements.push({ id: crypto.randomUUID(), productId: paper.id, delta: 20, reason: \"restock\", note: \"\", createdAt: now - 40 * DAY });\n    movements.push({ id: crypto.randomUUID(), productId: paper.id, delta: -15, reason: \"sale\", note: \"Office restock request\", createdAt: now - 5 * DAY });\n  }\n  if (drill) {\n    movements.push({ id: crypto.randomUUID(), productId: drill.id, delta: 15, reason: \"restock\", note: \"\", createdAt: now - 65 * DAY });\n    movements.push({ id: crypto.randomUUID(), productId: drill.id, delta: -5, reason: \"sale\", note: \"\", createdAt: now - 8 * DAY });\n    movements.push({ id: crypto.randomUUID(), productId: drill.id, delta: -1, reason: \"damaged\", note: \"Dropped in transit\", createdAt: now - 2 * DAY });\n  }\n  return movements;\n}\n",
  "src/lib/storage.ts": "import type { Movement, MovementReason, Product, Supplier } from \"../types\";\nimport { MOVEMENT_REASONS } from \"../types\";\n\nconst PRODUCTS_KEY = \"inventory-tracker:products\";\nconst SUPPLIERS_KEY = \"inventory-tracker:suppliers\";\nconst MOVEMENTS_KEY = \"inventory-tracker:movements\";\nconst SEEDED_KEY = \"inventory-tracker:seeded\";\n\nfunction isSupplier(value: unknown): value is Supplier {\n  if (!value || typeof value !== \"object\") return false;\n  const s = value as Record<string, unknown>;\n  return (\n    typeof s.id === \"string\" &&\n    typeof s.name === \"string\" &&\n    typeof s.email === \"string\" &&\n    typeof s.phone === \"string\" &&\n    typeof s.createdAt === \"number\"\n  );\n}\n\nfunction isProduct(value: unknown): value is Product {\n  if (!value || typeof value !== \"object\") return false;\n  const p = value as Record<string, unknown>;\n  return (\n    typeof p.id === \"string\" &&\n    typeof p.name === \"string\" &&\n    typeof p.sku === \"string\" &&\n    typeof p.category === \"string\" &&\n    typeof p.quantity === \"number\" &&\n    typeof p.reorderThreshold === \"number\" &&\n    typeof p.unitCost === \"number\" &&\n    typeof p.supplierId === \"string\" &&\n    typeof p.createdAt === \"number\"\n  );\n}\n\nfunction isReason(value: unknown): value is MovementReason {\n  return typeof value === \"string\" && MOVEMENT_REASONS.includes(value as MovementReason);\n}\n\nfunction isMovement(value: unknown): value is Movement {\n  if (!value || typeof value !== \"object\") return false;\n  const m = value as Record<string, unknown>;\n  return (\n    typeof m.id === \"string\" &&\n    typeof m.productId === \"string\" &&\n    typeof m.delta === \"number\" &&\n    isReason(m.reason) &&\n    typeof m.createdAt === \"number\"\n  );\n}\n\nexport function loadSuppliers(): Supplier[] {\n  try {\n    const raw = localStorage.getItem(SUPPLIERS_KEY);\n    if (!raw) return [];\n    const parsed = JSON.parse(raw);\n    return Array.isArray(parsed) ? parsed.filter(isSupplier) : [];\n  } catch {\n    return [];\n  }\n}\n\nexport function saveSuppliers(suppliers: Supplier[]): void {\n  try {\n    localStorage.setItem(SUPPLIERS_KEY, JSON.stringify(suppliers));\n  } catch {\n    // Storage full or unavailable — in-memory state still works this session.\n  }\n}\n\nexport function loadProducts(): Product[] {\n  try {\n    const raw = localStorage.getItem(PRODUCTS_KEY);\n    if (!raw) return [];\n    const parsed = JSON.parse(raw);\n    return Array.isArray(parsed) ? parsed.filter(isProduct) : [];\n  } catch {\n    return [];\n  }\n}\n\nexport function saveProducts(products: Product[]): void {\n  try {\n    localStorage.setItem(PRODUCTS_KEY, JSON.stringify(products));\n  } catch {\n    // Ignore — see saveSuppliers.\n  }\n}\n\nexport function loadMovements(): Movement[] {\n  try {\n    const raw = localStorage.getItem(MOVEMENTS_KEY);\n    if (!raw) return [];\n    const parsed = JSON.parse(raw);\n    if (!Array.isArray(parsed)) return [];\n    return parsed.filter(isMovement).map((m) => ({ ...m, note: typeof m.note === \"string\" ? m.note : \"\" }));\n  } catch {\n    return [];\n  }\n}\n\nexport function saveMovements(movements: Movement[]): void {\n  try {\n    localStorage.setItem(MOVEMENTS_KEY, JSON.stringify(movements));\n  } catch {\n    // Ignore — see saveSuppliers.\n  }\n}\n\nexport function hasSeeded(): boolean {\n  try {\n    return localStorage.getItem(SEEDED_KEY) === \"1\";\n  } catch {\n    return true;\n  }\n}\n\nexport function markSeeded(): void {\n  try {\n    localStorage.setItem(SEEDED_KEY, \"1\");\n  } catch {\n    // Ignore — see saveSuppliers.\n  }\n}\n",
  "src/main.tsx": "import React from \"react\";\nimport ReactDOM from \"react-dom/client\";\nimport App from \"./App\";\nimport \"./index.css\";\n\nReactDOM.createRoot(document.getElementById(\"root\")!).render(\n  <React.StrictMode>\n    <App />\n  </React.StrictMode>\n);\n",
  "src/types.ts": "export interface Supplier {\n  id: string;\n  name: string;\n  email: string;\n  phone: string;\n  createdAt: number;\n}\n\nexport interface Product {\n  id: string;\n  name: string;\n  sku: string;\n  category: string;\n  quantity: number;\n  reorderThreshold: number;\n  unitCost: number;\n  supplierId: string;\n  createdAt: number;\n}\n\nexport type MovementReason = \"restock\" | \"sale\" | \"damaged\" | \"correction\";\n\nexport const MOVEMENT_REASONS: MovementReason[] = [\"restock\", \"sale\", \"damaged\", \"correction\"];\n\nexport interface Movement {\n  id: string;\n  productId: string;\n  delta: number;\n  reason: MovementReason;\n  note: string;\n  createdAt: number;\n}\n",
  "tailwind.config.js": "/** @type {import('tailwindcss').Config} */\nexport default {\n  content: [\"./index.html\", \"./src/**/*.{js,ts,jsx,tsx}\"],\n  theme: {\n    extend: {},\n  },\n  plugins: [],\n};\n",
  "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"useDefineForClassFields\": true,\n    \"lib\": [\"ES2020\", \"DOM\", \"DOM.Iterable\"],\n    \"module\": \"ESNext\",\n    \"skipLibCheck\": true,\n    \"moduleResolution\": \"bundler\",\n    \"allowImportingTsExtensions\": true,\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true,\n    \"noEmit\": true,\n    \"jsx\": \"react-jsx\",\n    \"strict\": true,\n    \"noUnusedLocals\": true,\n    \"noUnusedParameters\": true,\n    \"noFallthroughCasesInSwitch\": true\n  },\n  \"include\": [\"src\"],\n  \"references\": [{ \"path\": \"./tsconfig.node.json\" }]\n}\n",
  "tsconfig.node.json": "{\n  \"compilerOptions\": {\n    \"composite\": true,\n    \"skipLibCheck\": true,\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"allowSyntheticDefaultImports\": true,\n    \"strict\": true\n  },\n  \"include\": [\"vite.config.ts\"]\n}\n",
  "vite.config.ts": "import { defineConfig } from \"vite\";\nimport react from \"@vitejs/plugin-react\";\n\nexport default defineConfig({\n  plugins: [react()],\n});\n",
};
